        # Determine the owner from the surrounding stones
        owners = set()
        for cx, cy in region:
            for nx, ny in ((cx+1, cy), (cx-1, cy), (cx, cy+1), (cx, cy-1)):
                if 0 <= nx < len(self.board[0]) and 0 <= ny < len(self.board):
                    cell = self.board[ny][nx]
                    if cell in (WHITE, BLACK):
                        owners.add(cell)

        if len(owners) == 1:
            return owners.pop(), region
        return NONE, region
