        for cx, cy in region:
            for nx, ny in self._neighbors(cx, cy):
                if self.board[ny][nx] in (WHITE, BLACK):
                    owners.add(self.board[ny][nx])

        if len(owners) == 1:
            return owners.pop(), region
        return NONE, region

    def _neighbors(self, x, y):
        for nx, ny in ((x+1, y), (x-1, y), (x, y+1), (x, y-1)):
